code_hint_css:
/* Apply to an SVG path with the checkmark path data. */
@keyframes demoStrokeDraw{from{stroke-dashoffset:70}to{stroke-dashoffset:0}}
.check-path{stroke-dasharray:70;stroke-dashoffset:0;animation:demoStrokeDraw 850ms ease-out both;}

/* A real counter updates text, not just opacity or position. */
.number {font-variant-numeric: tabular-nums;}
/* Animate integer textContent with requestAnimationFrame (0 → target) and honor reduced motion. */

/* Create 8 positioned .demo-burst-dot children; assign --bearing (0deg,45deg...) and --distance (40px). */
@keyframes atlasBurst{0%{opacity:1;transform:rotate(var(--bearing)) translateY(0) scale(.3)}45%{opacity:1}100%{opacity:0;transform:rotate(var(--bearing)) translateY(calc(-1 * var(--distance))) scale(.9)}}
@media (prefers-reduced-motion:reduce){.motion-target,.motion-target *{animation:none!important}}

/* Wrap each letter in a span and stagger animation-delay by 60ms per letter. */
@keyframes atlasKineticLetter{0%{opacity:0;transform:translateY(20px) rotate(-12deg)}65%{opacity:1;transform:translateY(-4px) rotate(3deg)}100%{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.motion-target,.motion-target *{animation:none!important}}

/* Apply ease-in, linear and ease-out separately to 3 dots; the displacement and duration remain identical. */
@keyframes atlasEasingTravel{from{transform:translateX(0)}to{transform:translateX(110px)}}
@media (prefers-reduced-motion:reduce){.motion-target,.motion-target *{animation:none!important}}

.blob-target{animation:atlasLiquid 1450ms ease-in-out both}
@keyframes atlasLiquid{0%{border-radius:58% 42% 59% 41%/44% 57% 43% 56%;transform:rotate(0) scale(1)}35%{border-radius:34% 66% 42% 58%/67% 32% 68% 33%;transform:rotate(14deg) scale(1.08,.92)}72%{border-radius:64% 36% 69% 31%/35% 72% 28% 65%;transform:rotate(-11deg) scale(.93,1.08)}100%{border-radius:58% 42% 59% 41%/44% 57% 43% 56%;transform:none}}
@media (prefers-reduced-motion:reduce){.motion-target,.motion-target *{animation:none!important}}

/* Clone the moving dot three times; apply progressively lower opacity and 70ms,140ms,210ms delays. */
@keyframes atlasTrail{from{transform:translateX(0)}to{transform:translateX(100px)}}
@media (prefers-reduced-motion:reduce){.motion-target,.motion-target *{animation:none!important}}

/* Add 12 dots and distribute --bearing at 30-degree increments; run once. */
@keyframes atlasBurst{0%{opacity:1;transform:rotate(var(--bearing)) translateY(0) scale(.3)}45%{opacity:1}100%{opacity:0;transform:rotate(var(--bearing)) translateY(calc(-1 * var(--distance))) scale(.9)}}
@media (prefers-reduced-motion:reduce){.motion-target,.motion-target *{animation:none!important}}

/* Create three positioned layers and assign --travel:7px,24px,50px. */
@keyframes atlasParallax{from{transform:translateX(0)}to{transform:translateX(var(--travel))}}
@media (prefers-reduced-motion:reduce){.motion-target,.motion-target *{animation:none!important}}
